If you wanna prevent agent from committing you can use the permissions I outlined, you will need to restart opencode after adding that but it will prevent agent from committing things

We do pass the signal, so this works:

```
import { type Plugin, tool } from "@opencode-ai/plugin"

export const CustomToolsPlugin: Plugin = async (pluginCtx) => {
  return {
    tool: {
      mytool: tool({
        description: "This is a custom tool",
        args: {
          foo: tool.schema.string(),
        },
        async execute(args, ctx) {
          await new Promise((resolve, reject) => {
            const timeout = setTimeout(resolve, 60000)
            ctx.abort.addEventListener(
              "abort",
              () => {
                clearTimeout(timeout)
                reject(new DOMException("Aborted", "AbortError"))
              },
              { once: true },
            )
          })
          return `Hello ${args.foo}!`
        },
      }),
    },
  }
}
```

But if you aren't referencing the signal then tools will appear to ignore the abort
